function automationSettings(){if(!automationDraft)automationDraft={enabled:automation?.enabled===true,minIntervalMinutes:automation?.minIntervalMinutes??3,maxIntervalMinutes:automation?.maxIntervalMinutes??5,scenarioIds:[...(automation?.scenarioIds||[])]};return automationDraft;}
function captureAutomationForm(){const form=$('#automation-form');if(!form?.elements)return;const d=automationSettings();d.enabled=form.elements.namedItem('enabled')?.checked===true;d.minIntervalMinutes=Number(form.elements.namedItem('minIntervalMinutes')?.value);d.maxIntervalMinutes=Number(form.elements.namedItem('maxIntervalMinutes')?.value);d.scenarioIds=[...form.querySelectorAll('[name="scenarioIds"]:checked')].map(input=>input.value);}
function automationIsDirty(){if(!automation||!automationDraft)return false;return JSON.stringify([automationDraft.enabled,automationDraft.minIntervalMinutes,automationDraft.maxIntervalMinutes,[...automationDraft.scenarioIds].sort()])!==JSON.stringify([automation.enabled===true,automation.minIntervalMinutes??3,automation.maxIntervalMinutes??5,[...(automation.scenarioIds||[])].sort()]);}
function syncAutomationControls(){const form=$('#automation-form'),button=form?.querySelector?.('[data-action="automation-dispatch"]');if(button)button.disabled=automationBusy||automationIsDirty()||!(automation?.scenarioAvailability||[]).some(s=>s.available===true);}
function automationRuntime(){
  const a=automation||{},last=a.lastRun,current=a.activeRun,status={disabled:'自动派工已关闭',scheduled:'等待下次随机派工',running:'任务执行中',awaiting_approval:'等待真人审批',waiting_model:'等待模型连接',waiting_task:'等待当前任务结束',dispatching:'正在随机派发',error:'派工异常'}[a.status]||(a.enabled?'等待调度':'自动派工已关闭');
  return `<div class="automation-state ${a.status==='awaiting_approval'?'approval-wait':''}"><span class="status-dot ${['error','waiting_model'].includes(a.status)?'warning':''}"></span><strong>${esc(status)}</strong>${a.pauseReason?`<p>${esc(a.pauseReason)}</p>`:''}</div><dl class="automation-times"><div><dt>下次派工</dt><dd>${a.enabled&&a.nextRunAt?esc(date(a.nextRunAt)):a.enabled?'当前任务结束后重新安排':'关闭'}</dd></div><div><dt>最近自动任务</dt><dd>${last?`${esc(last.title||scenario(last.scenarioId)?.title||last.scenarioId)}<small>${esc(STATUS[last.status]||last.status)} · ${esc(date(last.createdAt||a.lastDispatchedAt))}</small>`:'尚未派发'}</dd></div></dl>${current?`<div class="automation-current"><small>${current.id===(a.lastRunId||last?.id)?'当前随机任务':'当前办公任务'}</small><strong>${esc(current.title||scenario(current.scenarioId)?.title||'任务进行中')}</strong><span>${esc(STATUS[current.status]||current.status)}</span></div>`:''}${pendingAutomationRunId&&pendingAutomationRunId!==run?.id?'<p class="automation-deferred">自动任务已开始。关闭当前面板后展示现场，或主动查看任务。</p>':''}<div class="button-row automation-live-actions">${current||last||pendingAutomationRunId?'<button type="button" class="button" data-action="automation-view">查看本次任务</button>':''}<button type="button" class="button" data-action="automation-refresh" ${automationBusy?'disabled':''}>${icon('reset')}刷新状态</button></div>`;
}
function renderAutomation(){
  if(!automation)return `${header('自动派工','公司办公任务 · 由服务端持续调度')}<div id="automation-error">${automationError?errorBox(automationError):empty('正在读取派工设置…')}</div><button class="button" data-action="automation-refresh">${icon('reset')}重新读取</button></div>`;
  const a=automation,d=automationSettings(),availability=new Map((a.scenarioAvailability||[]).map(item=>[item.id,item])),profile=a.companyProfile||{},facts=Array.isArray(profile.verifiedFacts)?profile.verifiedFacts:[],sources=Array.isArray(profile.sources)?profile.sources:[],ready=[...availability.values()].filter(item=>item.available===true).length;
  return `${header('自动派工','按设定间隔派发任务')}<div class="automation-company"><strong>${esc(a.companyName||profile.name||'吉林云投莱森购数字科技有限公司')}</strong><span>${facts.length?`已收录 ${facts.length} 项公司资料`:'公司名称由你提供 · 业务事实待核实'} · ${ready} 类任务资料可用</span>${sources.length?`<details class="automation-sources"><summary>资料来源</summary>${sources.map(item=>{const url=safeUrl(typeof item==='string'?item:item.url);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(typeof item==='string'?short(item,90):item.title||short(url,90))}${icon('arrow')}</a>`:'';}).join('')}</details>`:''}</div><div id="automation-runtime">${automationRuntime()}</div><form id="automation-form" novalidate><label class="automation-switch"><input type="checkbox" name="enabled" ${d.enabled?'checked':''} ${automationBusy?'disabled':''}><span><strong>开启自动派工</strong><small>已有任务或等待真人审批时暂停派发</small></span></label><div class="automation-interval"><label class="office-field"><span class="field-label">最短间隔（分钟）</span><input class="field-input" type="number" name="minIntervalMinutes" min="1" max="60" step="1" value="${esc(d.minIntervalMinutes)}" required ${automationBusy?'disabled':''}></label><label class="office-field"><span class="field-label">最长间隔（分钟）</span><input class="field-input" type="number" name="maxIntervalMinutes" min="1" max="60" step="1" value="${esc(d.maxIntervalMinutes)}" required ${automationBusy?'disabled':''}></label></div><fieldset class="automation-scenarios"><legend>随机任务范围</legend>${catalog.scenarios.map(s=>{const item=availability.get(s.id),available=item?.available===true;return `<label class="automation-scenario ${available?'':'unavailable'}"><input type="checkbox" name="scenarioIds" value="${esc(s.id)}" ${available&&d.scenarioIds.includes(s.id)?'checked':''} ${!available||automationBusy?'disabled':''}><span><strong>${esc(s.title)}</strong><small>${esc(available?item.inputBasis||item.reason||'任务资料已就绪':item?.reason||'缺少可用资料，暂不派发')}</small></span></label>`;}).join('')}</fieldset><div id="automation-error" ${automationError?'':'hidden'}>${automationError?errorBox(automationError):''}</div><div class="form-actions"><button type="button" class="button" data-action="automation-dispatch" ${automationBusy||!ready||automationIsDirty()?'disabled':''} title="按已保存的范围随机派发；修改后请先保存">${icon('play')}${automationBusy?'正在处理':'立即随机派发'}</button><button type="submit" class="button button-primary" ${automationBusy?'disabled':''}>${icon('check')}保存设置</button></div></form></div>`;
}
function syncAutomationPanel(){if(panel?.type!=='automation')return;const runtime=$('#automation-runtime');if(automation&&runtime)runtime.innerHTML=automationRuntime();const error=$('#automation-error');if(error){error.hidden=!automationError;error.innerHTML=automationError?errorBox(automationError):'';}}
function setAutomationState(value,{baseline=false}={}){if(!value||typeof value!=='object')return;const previous=automationObservedRunId,id=value.lastRunId||value.lastRun?.id||null;automation=value;automationError='';automationObservedRunId=id;if(!baseline&&id&&id!==previous&&(previous!==null||value.activeRun?.id===id)){pendingAutomationRunId=id;if(panel&&panel.type!=='automation')toast('自动任务已开始，关闭当前面板后展示现场。');}syncAutomationPanel();if(!baseline)void adoptAutomationRun();}
function syncHealth(value){if(!value?.provider)return;health={...health,...value};renderHud();const form=$('#task-form');if(!form)return;const submit=form.querySelector?.('button[type="submit"]');if(submit)submit.disabled=busy||uploadPending(form.dataset.scenarioId)||alive()||!health.provider.ready;const warning=$('#task-provider-warning');if(warning)warning.hidden=!!health.provider.ready;}
async function refreshAutomation({quiet=true}={}){if(authRedirecting||automationPolling||automationBusy)return;automationPolling=true;const first=!automation,epoch=automationRequestEpoch;try{const results=await Promise.allSettled([api('/api/automation'),api('/api/health')]);if(authRedirecting||epoch!==automationRequestEpoch)return;if(results[1].status==='fulfilled')syncHealth(results[1].value);if(results[0].status!=='fulfilled')throw results[0].reason;const data=results[0].value;if(!data.automation)throw new Error('未读取到自动派工设置，请稍后重试。');setAutomationState(data.automation);if(first&&panel?.type==='automation')renderPanel(true);}catch(error){automationError=error.message||'自动派工状态暂时无法同步。';if(!quiet&&panel?.type==='automation'){if(!automation)renderPanel(true);else syncAutomationPanel();}}finally{automationPolling=false;}}
async function adoptAutomationRun(){
  if(adoptingAutomationRun||!pendingAutomationRunId||busy||panel||alive()&&run?.id!==pendingAutomationRunId)return;
  const id=pendingAutomationRunId;if(run?.id===id){pendingAutomationRunId=null;return;}adoptingAutomationRun=true;
  try{const data=await api(`/api/runs/${encodeURIComponent(id)}`);if(pendingAutomationRunId!==id||panel||busy||alive()&&run?.id!==id)return;if(!isAutomationRun(data.run)){pendingAutomationRunId=null;return;}pendingAutomationRunId=null;receive(data.run,{initial:TERMINAL.has(data.run.status)});if(!TERMINAL.has(data.run.status))subscribe(id);}catch(error){automationError=error.message||'自动任务暂时无法同步。';syncAutomationPanel();}finally{adoptingAutomationRun=false;}
}
async function saveAutomation(form){
  if(automationBusy)return;captureAutomationForm();const d=automationSettings(),available=new Set((automation?.scenarioAvailability||[]).filter(item=>item.available===true).map(item=>item.id));
  if(d.enabled){if(!Number.isInteger(d.minIntervalMinutes)||!Number.isInteger(d.maxIntervalMinutes)||d.minIntervalMinutes<1||d.maxIntervalMinutes>60||d.minIntervalMinutes>d.maxIntervalMinutes)throw new Error('间隔需为 1–60 分钟的整数，最短间隔不能超过最长间隔。');if(d.scenarioIds.some(id=>!available.has(id)))throw new Error('所选任务缺少可用资料，请重新选择。');if(!d.scenarioIds.length)throw new Error('请选择至少一类资料已就绪的任务。');}
  const payload=d.enabled?{enabled:true,minIntervalMinutes:d.minIntervalMinutes,maxIntervalMinutes:d.maxIntervalMinutes,scenarioIds:d.scenarioIds}:{enabled:false};
  automationBusy=true;automationRequestEpoch++;automationError='';renderPanel(true);try{const data=await api('/api/automation','PUT',payload);setAutomationState(data.automation);automationDraft=null;toast(d.enabled?'自动派工已开启，按随机间隔安排任务。':'自动派工已关闭；原间隔与任务范围保留，现有任务继续执行。');}finally{automationBusy=false;renderPanel(true);}
}
async function dispatchAutomation(){if(automationBusy)return;captureAutomationForm();if(automationIsDirty()){automationError='设置已修改，请先保存后再立即派发。';syncAutomationPanel();return;}automationBusy=true;automationRequestEpoch++;automationError='';renderPanel(true);try{const data=await api('/api/automation/dispatch','POST',{});setAutomationState(data.automation);if(data.run){pendingAutomationRunId=data.run.id;closePanel();}else{automationError=data.reason||data.automation?.pauseReason||'当前无法派发，请查看派工状态。';syncAutomationPanel();}}catch(error){automationError=error.message||'派工失败，请重试。';syncAutomationPanel();}finally{automationBusy=false;if(panel?.type==='automation')renderPanel(true);else void adoptAutomationRun();}}
async function viewAutomationRun(){const id=pendingAutomationRunId||automation?.activeRun?.id||automation?.lastRunId||automation?.lastRun?.id;if(!id)return;const data=await api(`/api/runs/${encodeURIComponent(id)}`);if(!data.run)return;if(pendingAutomationRunId===id)pendingAutomationRunId=null;receive(data.run,{initial:TERMINAL.has(data.run.status)});if(!TERMINAL.has(data.run.status))subscribe(id);openPanel('progress');}
function portrait(id){if(!id||id==='human')return `<span class="system-avatar ${id==='human'?'human':''}">${icon(id==='human'?'users':'network')}</span>`;const a=agent(id);return `<span class="ai-avatar" style="--avatar:${esc(a.color)}"><span class="avatar-letter">${esc(a.name.slice(0,1))}</span>${virtualPortrait(id)}<b>虚拟</b></span>`;}
