function humanPortrait(){return `<svg class="approval-human-avatar" viewBox="0 0 120 120" role="img" aria-label="真人负责人，暖色衣服的卡通人物"><circle cx="60" cy="60" r="58" fill="#f6e6c6"/><ellipse cx="60" cy="110" rx="43" ry="9" fill="#b69a73" opacity=".16"/><path d="M22 114v-16q0-26 24-31h28q24 5 24 31v16" fill="#c88f68" stroke="#9c7053" stroke-width="2"/><path d="M37 85l7 28m39-28-7 28" fill="none" stroke="#b47d5b" stroke-width="2"/><path d="M51 64v12q9 11 18 0V64" fill="#e5b18d" stroke="#bd8c6a" stroke-width="1.5"/><path d="M45 73l15 12-10 13-10-20m35-5L60 85l10 13 10-20" fill="#faefd9" stroke="#c3ab87" stroke-width="1.3"/><ellipse cx="60" cy="44" rx="26" ry="30" fill="#efc9a6" stroke="#ac8568" stroke-width="1.6"/><path d="M34 43q-8-32 23-34 34-1 31 35l-9-15q-15 8-29-6-3 11-16 20" fill="#50453c"/><path d="M50 57q10 9 20 0" fill="none" stroke="#a9755d" stroke-width="2" stroke-linecap="round"/><circle cx="49" cy="44" r="2.4" fill="#4a463d"/><circle cx="71" cy="44" r="2.4" fill="#4a463d"/><ellipse cx="42" cy="54" rx="5" ry="2.5" fill="#e5ac92" opacity=".65"/><ellipse cx="78" cy="54" rx="5" ry="2.5" fill="#e5ac92" opacity=".65"/><circle cx="60" cy="101" r="2" fill="#e9c792"/></svg>`;}
function toast(text){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=`<span class="toast-content"><span class="toast-symbol" aria-hidden="true">${icon('check')}</span><span class="toast-copy">${esc(text)}</span></span><span class="toast-progress" aria-hidden="true"></span>`;el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},4400);}
function authenticationError(){return Object.assign(new Error('登录已过期，请重新登录。'),{status:401});}
function redirectToLogin(){if(authRedirecting)return;authRedirecting=true;stream?.close();stream=null;clearTimeout(reconnectTimer);cancelApprovalOpen();window.location?.assign?.('/login');}
async function logout(){if(!session.enabled||logoutPending||authRedirecting)return;logoutPending=true;renderPanel(true);try{await api('/api/session/logout','POST',{});redirectToLogin();}finally{logoutPending=false;renderPanel(true);}}
async function api(path,method='GET',body){if(authRedirecting)throw authenticationError();const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});if(response.status===401){redirectToLogin();throw authenticationError();}let data;try{data=await response.json();}catch{throw new Error('服务未返回有效数据，请检查办公室服务。');}if(!response.ok)throw new Error(typeof data.error==='string'?data.error:data.error?.message||data.message||`请求失败（${response.status}）`);return data;}
function safeUrl(value){try{const u=new URL(String(value),location.origin);return /^https?:$/.test(u.protocol)?u.href:null;}catch{return null;}}
function artifactUrl(artifact){const u=safeUrl(artifact.url);return u&&new URL(u).origin===location.origin?u:null;}
function header(title,eyebrow=''){return `<div class="popover-inner"><div class="panel-grip" aria-hidden="true"></div>${eyebrow?`<div class="popover-eyebrow"><i aria-hidden="true"></i>${esc(eyebrow)}</div>`:''}<div class="popover-top"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="关闭操作面板">${icon('close')}</button></div>`;}
function openPanel(type,id=null,tab=null){if(panel?.type==='task')captureTaskForm();if(panel?.type==='automation')captureAutomationForm();if(type==='automation'&&panel?.type!=='automation')automationDraft=null;if(type==='approval')cancelApprovalOpen();panel={type,id,tab};panelSignature='';scene.setSelectedAgent(type==='agent'?id:null);scene.setSelectedNode(type==='node'?id:null);scene.setSelectedHuman?.(type==='human'?id:type==='approval'?approvalHumanId():null);$panel.classList.toggle('office-panel-opening',true);if(type==='agent'){const p=scene.getAgentAnchor(id),r=$scene.getBoundingClientRect();if(p&&(p.x+r.left<40||p.x+r.left>innerWidth-40))scene.focusAgent(id);}if(type==='human'){const point=scene.getHumanAnchor?.(id),rect=$scene.getBoundingClientRect();if(point&&(point.x+rect.left<40||point.x+rect.left>innerWidth-40))scene.focusHuman?.(id);}renderPanel(true);renderDock();renderNotices();if(type==='approval')$panel.focus({preventScroll:true});if(type==='automation')void refreshAutomation({quiet:false});}
function closePanel(){$panel.classList.toggle('office-panel-opening',false);if(panel?.type==='task')captureTaskForm();if(panel?.type==='automation')captureAutomationForm();panel=null;panelSignature='';$panel.hidden=true;scene.setSelectedAgent(null);scene.setSelectedNode(null);scene.setSelectedHuman?.(null);renderDock();renderNotices();syncApprovalFocus();void adoptAutomationRun();}
function errorBox(text){return `<div class="office-error" role="alert">${icon('info')}<span>${esc(text)}</span></div>`;}
function empty(text){return `<div class="office-empty">${esc(text)}</div>`;}
function resultText(value){if(typeof value==='string')return value;return value==null?'':JSON.stringify(value,null,2);}
function humanAvatar(id){const h=human(id);return `<span class="real-avatar" aria-label="${esc(h.name)}，真实员工职能角色">${humanPortrait()}<b>真实</b></span>`;}
function humanWork(id){const h=human(id),responsible=run&&humanForScenario(run.scenarioId)?.id===id,approval=id===approvalHumanId()&&!!run?.approval,deliveries=(run?.events||[]).filter(e=>e.type==='handoff'&&e.targetHumanId===id);if(approval)return {...h,status:'awaiting_approval',task:run.approval.title,action:'请审阅方案并明确批准或拒绝',result:'等待使用者操作',deliveries};if(responsible&&alive())return {...h,status:'waiting',task:run.title,action:'资料已提交，虚拟员工正在处理',result:'可查看真实执行记录',deliveries};if(responsible&&run?.artifacts?.length)return {...h,status:run.status==='completed'&&deliveries.some(e=>e.deliveryKind==='final_delivery')?'delivery':'files_available',task:run.title,action:run.status==='completed'&&deliveries.some(e=>e.deliveryKind==='final_delivery')?'查阅交付文件与证据':'查阅已保留文件与证据',result:run.status==='failed'?'任务失败，已保留过程证据':run.status==='cancelled'?'任务已取消，已保留过程证据':'等待使用者查阅与确认后续事项',deliveries};return {...h,status:'idle',task:'提供资料或接收交付',action:'选择本职能的办公任务',result:'由使用者操作',deliveries};}
function renderHuman(){const h=human(panel.id),state=humanWork(h.id),assigned=catalog.scenarios.filter(s=>h.id==='owner'||humanForScenario(s.id)?.id===h.id),receives=(run?.events||[]).filter(e=>e.sourceHumanId===h.id||e.targetHumanId===h.id||e.actor==='human'&&(e.humanId||e.data?.targetHumanId||'owner')===h.id);return `${header(h.name,'真实员工（由你操作）')}<div class="human-profile">${humanAvatar(h.id)}<span><strong>${esc(h.role||h.name)}</strong><small>职能角色 · 资料、审批和查阅由使用者操作</small></span></div><div class="human-duty">${esc(HUMAN_DUTIES[h.id]||h.role||h.name)}</div><div class="human-todo"><small>当前待办</small><strong>${esc(state.task)}</strong><p>${esc(state.action)}</p><span>${esc(state.result)}</span></div>${h.id===approvalHumanId()&&run?.approval?'<button class="button button-primary human-action" data-open="approval">审阅待审批方案</button>':''}${run&&(h.id==='owner'||humanForScenario(run.scenarioId)?.id===h.id)?`<div class="button-row"><button class="button" data-open="progress">查看任务进展</button>${run.artifacts?.length?'<button class="button button-primary" data-open="artifacts">查阅交付文件</button>':''}</div>`:''}${assigned.length?`<div class="office-section-label">提供资料并派发任务</div><div class="human-scenario-actions">${assigned.map(s=>`<button class="context-action" data-scenario="${esc(s.id)}" ${alive()?'disabled':''}>${icon(s.icon||'book')}<span>${esc(s.title)}<small>${esc(s.outputs.join(' · '))}</small></span>${icon('chevron')}</button>`).join('')}</div>`:''}${['owner','hr_owner'].includes(h.id)&&!run?.approval?'<div class="office-note">当前没有待审批事项。需要真人决定时，会在这里高亮请求。</div>':''}${receives.length?`<div class="office-section-label">真实交接记录</div>${receives.slice(-5).reverse().map(logMarkup).join('')}`:''}</div>`;}
function resultSummary(value,fallback){if(value&&typeof value==='object'&&typeof value.summary==='string')return value.summary;if(typeof value==='string'&&value.trimStart().startsWith('{')){try{const parsed=JSON.parse(value);if(typeof parsed?.summary==='string')return parsed.summary;}catch{const matched=value.match(/^\s*\{\s*"summary"\s*:\s*("(?:[^"\\]|\\.)*")/s);if(matched){try{return JSON.parse(matched[1]);}catch{}}if(typeof fallback?.summary==='string')return fallback.summary;}}return resultText(value);}
function failedVerificationReceipts(task){return (Array.isArray(task?.toolResults)?task.toolResults:[]).filter(entry=>entry.result?.evidence?.passed===false);}
function currentVerificationFailures(task){const latest=new Map();for(const entry of task?.toolResults||[])if(entry?.result?.evidence&&typeof entry.result.evidence.passed==='boolean')latest.set(entry.tool,entry);return [...latest.values()].filter(entry=>entry.result.evidence.passed===false);}
function hasVerificationIssues(value){if(value?.outcome&&value.status==='completed')return ['needs_review','incomplete','failed'].includes(value.outcome.validationStatus);return (value?.tasks||[]).some(task=>currentVerificationFailures(task).length>0);}
function verificationFailureMarkup(task){
  const receipts=failedVerificationReceipts(task);if(!receipts.length)return '';const unresolved=currentVerificationFailures(task).length>0;
  return `<details class="${unresolved?'verification-failure':'verification-history'}" data-evidence-key="verification-${esc(task.id)}"><summary>${icon('info')}<strong>${unresolved?'存在未通过项':'早前未通过，后续回执通过'}</strong><small>${receipts.length} 次早前核查回执</small></summary>${receipts.map((entry,index)=>{
    const evidence=entry.result.evidence,items=[];
    for(const [i,item]of [...(Array.isArray(evidence.tests)?evidence.tests:[]),...(Array.isArray(evidence.contractTests)?evidence.contractTests:[])].entries())if(item.passed===false)items.push((item.name||`测试 ${i+1}`)+(item.error?'：'+item.error:''));
    if(Array.isArray(evidence.checks)){for(const [i,item]of evidence.checks.entries())if(item?.passed===false||item?.ok===false)items.push(item.name||item.item||`检查 ${i+1}`);}
    else if(evidence.checks&&typeof evidence.checks==='object')for(const [name,passed]of Object.entries(evidence.checks))if(passed===false)items.push('检查未通过：'+name);
    if(typeof evidence.error==='string'&&evidence.error)items.push(evidence.error);for(const error of Array.isArray(evidence.errors)?evidence.errors:[])if(typeof error==='string'&&error)items.push(error);
    if(typeof evidence.integrity==='string'&&evidence.integrity!=='ok')items.push('完整性检查：'+evidence.integrity);
    if(Array.isArray(evidence.foreignKeyViolations)&&evidence.foreignKeyViolations.length)items.push(`外键检查发现 ${evidence.foreignKeyViolations.length} 条不一致记录`);
    const unique=[...new Set(items)];return `<section><h4>${esc(TOOLS[entry.tool]||entry.tool||'实际工具核查')}</h4><ul>${unique.length?unique.slice(0,12).map(item=>`<li>${esc(short(item,600))}</li>`).join(''):'<li>工具回执标记未通过，请查看原始回执。</li>'}${unique.length>12?`<li>另有 ${unique.length-12} 项，见原始回执。</li>`:''}</ul>${evidenceMarkup(entry.result,`verification-${task.id}-${index}`,'查看实际工具回执')}</section>`;
  }).join('')}</details>`;
}
function investmentFindingText(value){return String(value??'').replace(/\b(?:issuer_claim|source_supported|corroborated|conflict|unverified)\b/g,status=>({issuer_claim:'项目方自述',source_supported:'有来源支持',corroborated:'多来源说法',conflict:'证据冲突',unverified:'待核实'}[status]));}
function cancelApprovalOpen(){if(pendingApprovalOpen?.timer)clearTimeout(pendingApprovalOpen.timer);pendingApprovalOpen=null;}
function revealApproval(runId,approvalId){if(run?.id!==runId||run?.approval?.id!==approvalId)return;cancelApprovalOpen();const target=approvalHumanId();if(scene.focusHuman)scene.focusHuman(target);else scene.focusNode(human(target).nodeId);openPanel('approval',target);}
function scheduleApprovalOpen(){cancelApprovalOpen();const runId=run.id,approvalId=run.approval.id;pendingApprovalOpen={runId,approvalId,timer:setTimeout(()=>revealApproval(runId,approvalId),16000)};}
function onSceneDelivery(event){if(!pendingApprovalOpen||event?.targetHumanId!==approvalHumanId()||event.runId&&event.runId!==pendingApprovalOpen.runId)return;const approvalId=event.approvalId||event.data?.approvalId;if(approvalId===pendingApprovalOpen.approvalId)revealApproval(pendingApprovalOpen.runId,pendingApprovalOpen.approvalId);}
function evidenceMarkup(data,key='',label='查看返回证据'){if(!data)return '';const text=typeof data==='string'?data:JSON.stringify(data,null,2);const links=[];const walk=(v,depth=0)=>{if(depth>5||links.length>12)return;if(typeof v==='string'&&/^https?:\/\//.test(v)){const u=safeUrl(v);if(u&&!links.includes(u))links.push(u);}else if(Array.isArray(v))v.slice(0,15).forEach(x=>walk(x,depth+1));else if(v&&typeof v==='object')Object.values(v).slice(0,30).forEach(x=>walk(x,depth+1));};walk(data);return `<details class="evidence" data-evidence-key="${esc(key)}"><summary>${esc(label)}</summary>${links.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(short(u,100))}${icon('arrow')}</a>`).join('')}<pre>${esc(short(text,12000))}</pre></details>`;}
function logMarkup(event){const humanId=event.sourceHumanId||(event.actor==='human'?(event.humanId||event.data?.targetHumanId||'owner'):null),sourceId=event.sourceAgentId||event.agentId,name=humanId?human(humanId).name:agent(sourceId).name,target=event.targetHumanId?human(event.targetHumanId).name:event.targetAgentId?agent(event.targetAgentId).name:null;return `<article class="office-log ${esc(event.type)}"><div class="office-log-top">${humanId?humanAvatar(humanId):portrait(sourceId)}<strong>${esc(name)}${target?` → ${esc(target)}`:''}</strong><span class="event-type">${esc(TYPE[event.type]||event.type)}</span><time>${event.createdAt?new Date(event.createdAt).toLocaleTimeString('zh-CN',{hour12:false}):fmtTime(event.time)}</time></div><p>${esc(event.text)}</p>${event.tool?`<span class="tool-tag">${esc(TOOLS[event.tool]||event.tool)}</span>`:''}${evidenceMarkup(event.data??event.args,event.id,event.data?'查看返回证据':'查看调用参数')}</article>`;}
function runResultLabel(value=run){return value?.outcome?.label||STATUS[value?.status]||value?.status||'等待任务';}
function outcomeMarkup(value=run,{details=true,compact=false}={}){
 const o=value?.outcome;if(!o||typeof o!=='object')return '';
 const warning=['needs_review','incomplete','failed','cancelled'].includes(o.status);
 const overview=`<section class="result-overview" data-status="${esc(o.status)}"><span class="result-status ${warning?'warning':''}">${esc(STATUS[value.status]||value.status)}${o.example?' · 示例资料':''}</span><h3>${esc(o.label)}</h3><p>${esc(o.summary)}</p></section>`;
 if(!details)return overview;
 const findings=(o.findings||[]).length?`<ul class="result-findings">${o.findings.map(item=>`<li data-status="${esc(item.status)}"><strong>${esc(item.label)}</strong>${item.value!=null?`<span>${esc(item.value)}</span>`:''}${item.detail?`<small>${esc(item.detail)}</small>`:''}</li>`).join('')}</ul>`:'';
 const next=(o.nextActions||[]).length?`<section class="result-next"><h3>下一步</h3><ul>${o.nextActions.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>`:'';
 return overview+(compact&&findings+next?`<details class="result-detail"><summary>本次核验与后续事项</summary>${findings}${next}</details>`:findings+next);
}

function filePurpose(file){const ext=String(file.name||'').split('.').pop().toLowerCase();return ({html:'浏览器阅读版',md:'文本报告',xlsx:'可编辑报表',csv:'表格数据',sqlite:'SQLite 数据库',db:'数据库',sql:'SQL 脚本',json:'结构化数据与回执',conf:'隔离环境配置',log:'请求日志',txt:'文本记录'})[ext]||file.mimeType||'文件';}
function artifactMarkup(file){const url=artifactUrl(file);return `<div class="office-artifact">${icon(file.mimeType?.includes('sqlite')?'layers':'book')}<span><strong>${esc(file.name)}</strong><small>${esc(filePurpose(file))} · ${bytes(file.bytes||0)}</small></span>${url?`<a class="button" href="${esc(url)}" download>${icon('download')}下载</a>`:'<span>链接不可用</span>'}</div>`;}
