  const pending=run?.approval&&approvalHumanId()==='owner',management=(run?.tasks||[]).filter(t=>t.nodeId==='general_office'||t.agentId==='boss'),handoffs=(run?.events||[]).filter(e=>e.sourceNodeId==='general_office'||e.targetNodeId==='general_office'||e.targetHumanId==='owner'||e.sourceHumanId==='owner');
