function renderNode(){if(panel.id==='general_office')return renderGeneralOffice();const id=panel.id,s=scenario(NODE_SCENARIO[id]);const events=run?.events.filter(e=>run.tasks.find(t=>t.id===e.taskId)?.nodeId===id)||[];return `${header(NODE_NAMES[id]||id,'工作区动作')}${s?`<button class="context-action" data-scenario="${esc(s.id)}">${icon(s.icon)}<span>${esc(s.title)}<small>${esc(s.outputs.join(' · '))}</small></span>${icon('chevron')}</button>`:''}<div class="office-section-label">本次工作记录 · ${events.length}</div>${events.length?events.slice(-5).reverse().map(logMarkup).join(''):empty('该工作区尚未执行任务。')}<button class="button" data-open="tasks">查看全部办公任务</button></div>`;}
function renderMore(){return `${header('办公动作')}<div class="more-actions"><button class="button" data-open="automation">${icon('activity')}自动派工</button><button class="button" data-open="history">${icon('clock')}任务历史</button><button class="button" data-open="connection">${icon('activity')}模型连接</button><button class="button" data-open="progress">${icon('layers')}任务分工</button><button class="button" data-action="refresh">${icon('reset')}刷新状态</button>${session.enabled?`<button class="button" data-action="logout" ${logoutPending?'disabled':''}>${icon('arrow')}退出登录</button>`:''}${alive()?`<button class="button button-danger" data-action="cancel">${icon('close')}取消当前任务</button>`:''}</div><div class="human-identity">${icon('users')}<span><strong>真人负责人：你</strong><small>虚拟员工负责岗位执行；真实员工提供资料、审批并确认业务结果。</small></span></div></div>`;}
function renderPanel(force=false){if(!panel)return;const frozen=panel.type==='task'||panel.type==='agent'&&panel.tab==='config'||panel.type==='approval'||panel.type==='automation';const sig=JSON.stringify([panel,frozen?'':run?.updatedAt,panel.type==='approval'?run?.approval?.id:null,panel.type==='approval'?run?.status:null,frozen?'':health.provider?.ready,frozen?'':health.provider?.message,busy,runs.length]);if(!force&&sig===panelSignature)return;panelSignature=sig;const scroll=$panel.scrollTop,opened=new Set([...$panel.querySelectorAll('details[data-evidence-key][open]')].map(d=>d.dataset.evidenceKey));const renderers={tasks:renderTasks,task:renderTask,employees:renderEmployees,human:renderHuman,agent:renderAgent,progress:renderProgress,logs:renderLogs,artifacts:renderArtifacts,approval:renderApproval,connection:renderConnection,history:renderHistory,node:renderNode,more:renderMore,automation:renderAutomation};$content.innerHTML=(renderers[panel.type]||renderTasks)();$panel.hidden=false;$panel.className=`scene-popover glass office-panel ${['task','progress','logs','artifacts','history','automation'].includes(panel.type)?'wide':''} ${panel.type==='approval'?'approval':''} ${$panel.classList.contains('office-panel-opening')?'office-panel-opening':''}`;$panel.querySelectorAll('details[data-evidence-key]').forEach(d=>{if(opened.has(d.dataset.evidenceKey))d.open=true;});$panel.setAttribute('role',panel.type==='approval'?'dialog':'complementary');$panel.setAttribute('aria-modal',String(panel.type==='approval'));$panel.setAttribute('aria-label',panel.type==='approval'?'真人负责人审批对话框':'场景操作面板');$panel.scrollTop=scroll;syncApprovalFocus();positionOverlays();}
function updateScene(){const agents=run?.agents?.length?run.agents:catalog.agents.map(a=>({...a,configured:true,selected:true,status:'idle'}));scene.update({runId:run?.id||null,runStatus:run?.status||'idle',animateEvents:sceneAnimateEvents,nodes:run?.nodes||{},agents,humans:HUMAN_EMPLOYEES.map(h=>humanWork(h.id)),logs:(run?.events||[]).filter(e=>!sceneBaselineEvents.has(e.id)),humanApproval:!!run?.approval,approvalHumanId:approvalHumanId()});}
function render(){renderHud();renderDock();renderPanel();updateScene();renderNotices();}
function positionOverlays(){if(!$('#lab'))return;const bounds=$('#lab').getBoundingClientRect(),origin=$scene.getBoundingClientRect(),w=bounds.width,h=bounds.height;if(panel&&!$panel.hidden){const b=$panel.getBoundingClientRect(),anchor=panel.type==='agent'?scene.getAgentAnchor(panel.id):panel.type==='human'?(scene.getHumanAnchor?.(panel.id)||null):panel.type==='node'?scene.getNodeAnchor(panel.id):null;let left=(w-b.width)/2,top=(h-b.height)/2-8;if(anchor&&w>850){const x=anchor.x+origin.left-bounds.left,y=anchor.y+origin.top-bounds.top;left=x+40+b.width<w-16?x+40:x-b.width-40;top=y-100;}$panel.style.left=`${Math.max(12,Math.min(w-b.width-12,left))}px`;$panel.style.top=`${Math.max(12,Math.min(h-b.height-88,top))}px`;}
const occupied=[];for(const [id]of notices){const el=noticeLayer.querySelector(`[data-notice="${id}"]`),p=scene.getAgentAnchor(id);if(!el||!p)continue;const ew=el.offsetWidth,eh=el.offsetHeight;let x=Math.max(12,Math.min(w-ew-12,p.x+origin.left-bounds.left-ew/2)),y=Math.max(104,Math.min(h-eh-94,p.y+origin.top-bounds.top-eh-35));for(const b of occupied)if(x<b.x+b.w+8&&x+ew>b.x-8&&y<b.y+b.h+8&&y+eh>b.y-8){y=Math.min(h-eh-94,b.y+b.h+10);if(y<b.y+b.h&&w>650)x=Math.max(12,Math.min(w-ew-12,b.x+ew+12));}el.style.left=`${x}px`;el.style.top=`${y}px`;occupied.push({x,y,w:ew,h:eh});}}
function receive(next,{initial=false}={}){if(!next)return;if(isAutomationRun(next)&&pendingAutomationRunId===next.id)pendingAutomationRunId=null;const approvalResolved=panel?.type==='approval'&&run?.approval&&!next.approval,wasAwaiting=!!run?.approval;const changed=run?.id!==next.id;if(changed){cancelApprovalOpen();sceneBaselineEvents.clear();seenEvents.clear();notices.clear();noticeQueue.splice(0);lastApprovalId=null;}if(initial){for(const e of next.events||[])sceneBaselineEvents.add(e.id);}sceneAnimateEvents=!initial;run=next;if(!next.approval)cancelApprovalOpen();runs=[next,...runs.filter(r=>r.id!==next.id)].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));for(const e of next.events||[]){if(seenEvents.has(e.id))continue;seenEvents.add(e.id);if(!initial&&e.type==='result'&&e.agentId){const task=next.tasks.find(t=>t.id===e.taskId);noticeQueue.push({id:e.id,agentId:e.agentId,task:task?.title||agent(e.agentId).role,action:e.tool&&TOOLS[e.tool]||TOOLS[task?.toolResults?.at(-1)?.tool]||task?.action||'执行岗位任务',result:currentVerificationFailures(task).length?'存在未通过项，请展开任务中的实际工具回执。':e.text||resultText(task?.result),failed:currentVerificationFailures(task).length>0,remaining:11000});}}
if(wasAwaiting&&!next.approval)scene.resetView();if(approvalResolved)openPanel('progress');if(next.approval&&next.approval.id!==lastApprovalId){lastApprovalId=next.approval.id;if(initial)revealApproval(next.id,next.approval.id);else scheduleApprovalOpen();}if(TERMINAL.has(next.status)){stream?.close();stream=null;clearTimeout(reconnectTimer);connectionState='closed';if(changed||!initial)toast(next.status==='completed'?'任务已交付，可在「产物」下载文件':next.status==='failed'?'任务失败，证据已保留，可查看原因后重试':'任务已取消');}render();}
function subscribe(id){stream?.close();clearTimeout(reconnectTimer);connectionState='connecting';stream=new EventSource(`/api/runs/${encodeURIComponent(id)}/events`);stream.addEventListener('state',event=>{try{const data=JSON.parse(event.data);connectionState='live';receive(data.run);}catch(error){console.error('Invalid run state',error);}});stream.onopen=()=>{connectionState='live';renderHud();};stream.onerror=()=>{if(!alive())return;connectionState='reconnecting';renderHud();clearTimeout(reconnectTimer);reconnectTimer=setTimeout(async()=>{try{const data=await api(`/api/runs/${encodeURIComponent(id)}`);if(run?.id===id)receive(data.run);}catch{toast('暂时无法同步任务，连接恢复后会自动继续。');}},5000);};}
function showFieldError(id,error){if(error?.status===401)return;const el=$(id);if(el){el.innerHTML=errorBox(error.message||String(error));el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
function captureTaskForm(){const form=$('#task-form');if(!form)return;const id=form.dataset.scenarioId,d=taskDraft(id);for(const f of scenario(id).fields){if(f.type==='file')continue;const control=form.elements.namedItem(f.name);if(control)d[f.name]=f.type==='checkbox'?control.checked===true:f.type==='number'&&control.value!==''?Number(control.value):control.value;}setInputSource(id,inputSource[id]==='example'?'example':'user');}
async function readUpload(file,scenarioId,fieldName){if(file.size===0)throw new Error('文件为空，请选择有内容的资料。');if(file.size>8*1024*1024)throw new Error('单个文件最大 8 MB，请精简资料后再上传。');const ext=file.name.split('.').pop().toLowerCase();const formats=fileFormats(scenarioId,fieldName);if(!formats.includes(ext))throw new Error('此任务支持 '+formats.map(t=>t.toUpperCase()).join(' / ')+' 文件。文本请使用 UTF-8 编码。');if(ext==='xlsx'){const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));return {name:file.name,base64:btoa(binary)};}const text=await file.text();if(scenarioId==='investment'){const limit=fieldName==='financials'?240000:24000;if(text.length>limit)throw new Error('此项投资资料最多 '+limit+' 字符，请精简后上传。');}return {name:file.name,text};}
async function startTask(form){if(busy)return;captureTaskForm();const id=form.dataset.scenarioId;if(uploadPending(id))throw new Error('文件仍在读取，请完成后再派工。');const s=scenario(id),input={...taskDraft(id),example:inputSource[id]==='example',isExample:inputSource[id]==='example',_source:inputSource[id]==='example'?'example':'user'};if(id==='onboarding')delete input._source;for(const f of s.fields){const v=input[f.name];if(!f.required&&v==='')delete input[f.name];if(f.required&&(v==null||v===''||f.type==='file'&&!v||f.type==='checkbox'&&v!==true))throw new Error(`请提供${f.label}，也可以明确选择「使用示例」。`);}busy=true;renderPanel(true);try{const data=await api('/api/runs','POST',{scenarioId:id,input,agentConfigs:catalog.agents.map(a=>({id:a.id,instructions:config(a.id).instructions,tools:config(a.id).tools}))});closePanel();receive(data.run);subscribe(data.run.id);toast('任务已派发，虚拟员工开始执行。');}finally{busy=false;render();}}
async function toggleFullscreen(){
 if(fullscreenPending)return;
 const current=document.fullscreenElement||document.webkitFullscreenElement,target=document.documentElement;
 const change=current?(document.exitFullscreen||document.webkitExitFullscreen):(target.requestFullscreen||target.webkitRequestFullscreen);
 if(typeof change!=='function'){toast('当前浏览器不支持页面全屏，可使用浏览器的全屏功能。');return;}
 fullscreenPending=true;
 try{await change.call(current?document:target);}catch{toast('未能切换全屏，请重试或使用浏览器的全屏功能。');}
 finally{fullscreenPending=false;renderDock();positionOverlays();}
}
