async function action(name){if(name==='view-2d'||name==='view-3d')return switchSceneMode(name.slice(5));if(name==='logout')return logout();if(name==='automation-refresh')return refreshAutomation({quiet:false});if(name==='automation-dispatch')return dispatchAutomation();if(name==='automation-view')return viewAutomationRun();if(name==='fullscreen')return toggleFullscreen();if(busy)return;if(name==='check-provider'){automationRequestEpoch++;busy=true;renderPanel(true);try{const data=await api('/api/provider/check','POST',{});health.provider=data.provider;toast(data.provider.ready?'模型连接成功':data.provider.message||'模型尚未连接');}finally{busy=false;render();}}else if(name==='refresh'){automationRequestEpoch++;const [h,r]=await Promise.all([api('/api/health'),api('/api/runs')]);health=h;runs=r.runs||[];if(run){const found=runs.find(x=>x.id===run.id);if(found)receive(found,{initial:true});}render();toast('状态已更新');}else if(name==='cancel'){if(!alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/cancel`,'POST',{});receive(data.run);openPanel('progress');}finally{busy=false;render();}}else if(name==='retry'){if(!run||alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/retry`,'POST',{});closePanel();receive(data.run);subscribe(data.run.id);}finally{busy=false;render();}}}
document.addEventListener('click',async event=>{const button=event.target.closest('button,[data-open]');if(!button)return;try{if(button.hasAttribute('data-close'))return closePanel();if(button.dataset.open)return openPanel(button.dataset.open);if(button.dataset.human)return openHuman(button.dataset.human);if(button.dataset.agent)return openPanel('agent',button.dataset.agent,'work');if(button.dataset.agentTab){panel.tab=button.dataset.agentTab;return renderPanel(true);}if(button.dataset.scenario){if(alive())return toast('请先等待当前任务完成，或取消当前任务。');return openPanel('task',button.dataset.scenario);}if(button.hasAttribute('data-investment-template')){button.disabled=true;try{await downloadInvestmentTemplate();}finally{button.disabled=false;}return;}if(button.hasAttribute('data-finance-template')){button.disabled=true;try{await downloadFinanceTemplate();}finally{button.disabled=false;}return;}if(button.dataset.onboardingReal){if(busy||panel?.type!=='task'||panel.id!=='onboarding')return;delete drafts.onboarding;setInputSource('onboarding','user');renderPanel(true);toast('已清空虚构资料，请填写真实员工信息并重新确认录用。');return;}if(button.dataset.example){captureTaskForm();const id=button.dataset.example;busy=true;renderPanel(true);try{const data=await api(`/api/examples/${encodeURIComponent(id)}`);drafts[id]=data.input;setInputSource(id,'example');toast('已载入明确标记的示例资料，可修改后派工。');}finally{busy=false;renderPanel(true);}return;}if(button.dataset.clearFile){captureTaskForm();const id=panel.id;delete taskDraft(id)[button.dataset.clearFile];setInputSource(id,'user');return renderPanel(true);}if(button.dataset.action)return await action(button.dataset.action);if(button.dataset.approval){if(busy||!run?.approval)return;const note=$('#approval-note')?.value||'',approvalId=run.approval.id;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/approval`,'POST',{approved:button.dataset.approval==='true',note,approvalId});closePanel();receive(data.run);if(!TERMINAL.has(data.run.status))subscribe(data.run.id);}catch(error){showFieldError('#approval-error',error);}finally{busy=false;render();}return;}if(button.dataset.run){const data=await api(`/api/runs/${encodeURIComponent(button.dataset.run)}`);receive(data.run,{initial:true});if(!TERMINAL.has(data.run.status))subscribe(data.run.id);else{stream?.close();stream=null;}openPanel('progress');return;}if(button.dataset.dismissNotice){notices.delete(button.dataset.dismissNotice);renderNotices();return;}}catch(error){showFieldError(panel?.type==='connection'?'#connection-error':panel?.type==='task'?'#task-error':'#missing',error);}});
document.addEventListener('submit',async event=>{if(event.target.id==='automation-form'){event.preventDefault();try{await saveAutomation(event.target);}catch(error){showFieldError('#automation-error',error);}}else if(event.target.id==='task-form'){event.preventDefault();try{await startTask(event.target);}catch(error){showFieldError('#task-error',error);}}else if(event.target.id==='agent-form'){event.preventDefault();if(alive())return showFieldError('#agent-error',new Error('任务执行期间配置已锁定。'));const form=event.target,id=form.dataset.agentId,instructions=form.elements.instructions.value.trim(),tools=[...form.querySelectorAll('[name="tools"]:checked')].map(el=>el.value);if(!instructions)return showFieldError('#agent-error',new Error('请填写具体职责。'));if(!tools.length)return showFieldError('#agent-error',new Error('至少保留一个工具。'));configs[id]={instructions,tools};try{localStorage.setItem(CONFIG_KEY,JSON.stringify(configs));}catch{toast('配置已应用，但浏览器存储不可用。');}toast(`${agent(id).name}的职责与工具已保存，下次派工生效。`);panel.tab='work';renderPanel(true);}});
document.addEventListener('change',async event=>{const input=event.target;if(input.closest('#automation-form')){captureAutomationForm();syncAutomationControls();return;}if(input.type==='file'&&input.closest('#task-form')){captureTaskForm();const id=panel.id;try{if(input.files[0]){await handleUpload(id,input.name,input.files[0]);}}catch(error){input.value='';showFieldError('#task-error',error);}}else if(input.closest('#task-form')){captureTaskForm();setInputSource(panel.id,inputSource[panel.id]==='example'?'example':'user');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&panel)closePanel();});
$('#zoom-in').addEventListener('click',()=>scene.zoom(.15));$('#zoom-out').addEventListener('click',()=>scene.zoom(-.15));$('#zoom-fit').addEventListener('click',()=>{$scene.classList.toggle('overview');scene.resetView();});$('#topology-toggle').addEventListener('click',event=>{topology=!topology;scene.setTopology(topology);event.currentTarget.classList.toggle('active',topology);event.currentTarget.setAttribute('aria-pressed',String(topology));});
function renderNotices(){noticeLayer.hidden=!!panel;const capacity=innerWidth<720?1:2;while(notices.size>capacity){const [id,notice]=[...notices.entries()].at(-1);notices.delete(id);noticeQueue.unshift(notice);}while(notices.size<capacity&&noticeQueue.length){const index=noticeQueue.findIndex(n=>!notices.has(n.agentId));if(index<0)break;const next=noticeQueue.splice(index,1)[0];notices.set(next.agentId,next);}const markup=[...notices.values()].map(n=>`<article class="employee-notice ${n.failed?'notice-review':'notice-delivered'}" data-notice="${esc(n.agentId)}" data-notice-id="${esc(n.id||n.agentId)}"><div class="notice-signal" aria-hidden="true"><i></i><i></i><i></i></div><div class="employee-notice-head"><button data-agent="${esc(n.agentId)}">${portrait(n.agentId)}<span><strong>${esc(agent(n.agentId).name)} <small>虚拟员工</small></strong><em>${esc(agent(n.agentId).role)}</em></span></button><button class="icon-button" data-dismiss-notice="${esc(n.agentId)}" aria-label="收起${esc(agent(n.agentId).name)}的行动提示">${icon('close')}</button></div><dl><div><dt><span class="notice-sequence">01</span>任务</dt><dd>${esc(n.task)}</dd></div><div><dt><span class="notice-sequence">02</span>行动</dt><dd>${esc(short(resultSummary(n.action),220))}</dd></div><div class="notice-result"><dt><span class="notice-sequence">03</span>结果</dt><dd>${esc(short(resultSummary(n.result),300))}</dd></div></dl></article>`).join('');if(markup!==lastNoticeMarkup){noticeLayer.innerHTML=markup;lastNoticeMarkup=markup;}positionOverlays();}
let noticeTick=performance.now();setInterval(()=>{const now=performance.now(),elapsed=now-noticeTick;noticeTick=now;if(panel)return;let changed=false;for(const [id,n]of notices){n.remaining-=elapsed;if(n.remaining<=0){notices.delete(id);changed=true;}}if(changed)renderNotices();},500);
setInterval(()=>{void refreshAutomation();},8000);
window.addEventListener('resize',()=>{renderNotices();positionOverlays();});
async function boot(){renderHud();renderDock();try{const results=await Promise.allSettled([api('/api/catalog'),api('/api/health'),api('/api/runs'),api('/api/automation'),api('/api/session')]);if(authRedirecting)return;if(results[0].status!=='fulfilled')throw results[0].reason;catalog=results[0].value;try{const saved=JSON.parse(localStorage.getItem(CONFIG_KEY)||'{}');for(const a of catalog.agents){const c=saved[a.id];if(c&&typeof c.instructions==='string'&&Array.isArray(c.tools))configs[a.id]={instructions:c.instructions,tools:c.tools.filter(t=>a.tools.includes(t))};}}catch{}if(results[1].status==='fulfilled')health=results[1].value;else health.provider={ready:false,message:results[1].reason.message};if(results[2].status==='fulfilled')runs=results[2].value.runs||[];if(results[3].status==='fulfilled')setAutomationState(results[3].value.automation,{baseline:true});if(results[4].status==='fulfilled')session=results[4].value.session||session;const current=runs.find(r=>!TERMINAL.has(r.status))||runs[0];if(current){receive(current,{initial:true});if(!TERMINAL.has(current.status))subscribe(current.id);}render();void restoreSceneMode();}catch(error){if(error?.status===401)return;health.provider={ready:false,message:error.message};render();openPanel('connection');}}
boot();
